import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';

const Register = () => {
  const [step, setStep] = useState(1);
  const [submitted, setSubmitted] = useState(false);
  const [agreed, setAgreed] = useState(false);
  const navigate = useNavigate();

  const [formData, setFormData] = useState({
    email: '', password: '', firstName: '', lastName: '', country: '', phone: ''
  });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  if (submitted) {
    return (
      <div className="min-h-screen bg-[#0A0E1A] flex items-center justify-center p-4">
        <div className="w-full max-w-sm bg-slate-900/60 border border-slate-800 rounded-2xl p-10 text-center shadow-xl">
          <div className="w-14 h-14 rounded-full bg-emerald-500/10 border border-emerald-500/30 flex items-center justify-center text-emerald-400 text-2xl mx-auto mb-5">✓</div>
          <h2 className="text-white font-bold text-lg mb-2">Vérifie ta boîte mail</h2>
          <p className="text-slate-400 text-sm">Un lien d'activation a été envoyé à<br /><span className="text-slate-200">{formData.email}</span></p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#0A0E1A] flex items-center justify-center p-4">
      <div className="w-full max-w-sm">
        <div className="flex items-center gap-2.5 justify-center mb-8">
          <div className="w-9 h-9 rounded-lg bg-gradient-to-br from-blue-500 to-cyan-400 flex items-center justify-center font-black text-[#0A0E1A] text-lg shadow-lg shadow-blue-500/20">A</div>
          <span className="text-lg font-extrabold tracking-tight text-white">AVALON <span className="text-blue-400 font-medium">SECURE</span></span>
        </div>

        <div className="bg-slate-900/60 border border-slate-800 rounded-2xl p-8 shadow-xl">
          <h2 className="text-white font-bold text-lg mb-1 text-center">Créer un compte</h2>
          <p className="text-slate-500 text-xs text-center mb-6">Étape {step} sur 2</p>

          {step === 1 ? (
            <div className="space-y-3">
              <button className="w-full bg-white hover:bg-slate-100 text-slate-900 font-semibold py-2.5 rounded-lg text-sm transition-colors">
                Continuer avec Google
              </button>
              <div className="flex items-center gap-3 py-1">
                <div className="flex-1 h-px bg-slate-800"></div>
                <span className="text-[11px] text-slate-600 uppercase">ou</span>
                <div className="flex-1 h-px bg-slate-800"></div>
              </div>
              <input
                name="email" type="email" placeholder="Email" onChange={handleChange}
                className="w-full bg-slate-950 border border-slate-800 text-white px-4 py-2.5 rounded-lg text-sm outline-none focus:border-blue-500 transition-colors"
              />
              <input
                name="password" type="password" placeholder="Mot de passe" onChange={handleChange}
                className="w-full bg-slate-950 border border-slate-800 text-white px-4 py-2.5 rounded-lg text-sm outline-none focus:border-blue-500 transition-colors"
              />
              <div className="h-1 bg-slate-800 rounded-full overflow-hidden">
                <div
                  className={`h-full transition-all ${formData.password.length > 8 ? 'bg-emerald-500' : 'bg-red-500'}`}
                  style={{ width: `${Math.min(formData.password.length * 10, 100)}%` }}
                ></div>
              </div>
              <button
                onClick={() => setStep(2)}
                disabled={!formData.email || !formData.password}
                className="w-full bg-blue-600 hover:bg-blue-500 disabled:bg-slate-800 disabled:text-slate-600 text-white font-semibold py-2.5 rounded-lg text-sm transition-colors mt-2"
              >
                Suivant
              </button>
            </div>
          ) : (
            <div className="space-y-3">
              <input name="firstName" type="text" placeholder="Prénom" onChange={handleChange} className="w-full bg-slate-950 border border-slate-800 text-white px-4 py-2.5 rounded-lg text-sm outline-none focus:border-blue-500 transition-colors" />
              <input name="lastName" type="text" placeholder="Nom" onChange={handleChange} className="w-full bg-slate-950 border border-slate-800 text-white px-4 py-2.5 rounded-lg text-sm outline-none focus:border-blue-500 transition-colors" />
              <input name="country" type="text" placeholder="Pays" onChange={handleChange} className="w-full bg-slate-950 border border-slate-800 text-white px-4 py-2.5 rounded-lg text-sm outline-none focus:border-blue-500 transition-colors" />
              <input name="phone" type="tel" placeholder="Téléphone" onChange={handleChange} className="w-full bg-slate-950 border border-slate-800 text-white px-4 py-2.5 rounded-lg text-sm outline-none focus:border-blue-500 transition-colors" />

              {/* ENGAGEMENT ÉTHIQUE — obligatoire */}
              <label className="flex items-start gap-3 bg-slate-950/60 border border-slate-800 rounded-lg p-4 cursor-pointer">
                <input
                  type="checkbox"
                  checked={agreed}
                  onChange={(e) => setAgreed(e.target.checked)}
                  className="mt-0.5 w-4 h-4 accent-blue-500 shrink-0"
                />
                <span className="text-xs text-slate-400 leading-relaxed">
                  Je m'engage à n'utiliser les compétences acquises sur cette plateforme que dans un cadre légal et autorisé (audits sur systèmes m'appartenant ou avec accord écrit du propriétaire). Toute utilisation malveillante engage ma seule responsabilité.
                </span>
              </label>

              <button
                onClick={() => setSubmitted(true)}
                disabled={!agreed}
                className="w-full bg-emerald-600 hover:bg-emerald-500 disabled:bg-slate-800 disabled:text-slate-600 text-white font-semibold py-2.5 rounded-lg text-sm transition-colors mt-2"
              >
                Créer le compte
              </button>
            </div>
          )}
        </div>

        <p className="text-center text-slate-500 text-xs mt-6">
          Déjà inscrit ? <Link to="/login" className="text-blue-400 hover:text-blue-300 font-semibold">Se connecter</Link>
        </p>
      </div>
    </div>
  );
};
export default Register;
